const { Scalekit } = require('@scalekit-sdk/node');
const fs = require('fs');
const path = require('path');

async function main() {
  const trialId = fs.readFileSync('/logs/trial_id', 'utf8').trim();
  const externalId = 'ext_org_' + trialId;

  const scalekit = new Scalekit(
    process.env.SCALEKIT_ENVIRONMENT_URL,
    process.env.SCALEKIT_CLIENT_ID,
    process.env.SCALEKIT_CLIENT_SECRET
  );

  try {
    console.log('Creating organization...');
    const organization = await scalekit.organization.createOrganization({
      display_name: 'Harbor Test Org',
      external_id: externalId
    });
    console.log(`Created organization: ${organization.id}`);

    console.log('Listing organizations...');
    const organizations = await scalekit.organization.listOrganizations();

    // The listOrganizations might return an object with a list property or just an array.
    // Usually it returns { organizations: [...] } or just [...]
    const orgList = organizations.organizations || organizations;
    const foundOrg = orgList.find(org => org.external_id === externalId);

    if (foundOrg) {
      console.log(`Found organization in list: ${foundOrg.id}`);
      fs.writeFileSync('/home/user/scalekit-orgs/org_id.txt', foundOrg.id);
      console.log('Wrote org_id.txt');
    } else {
      console.error('Organization not found in list!');
      process.exit(1);
    }
  } catch (error) {
    console.error('Error:', error);
    process.exit(1);
  }
}

